import requests
from collections import Counter

headers = {"Authorization": "token XXX"}


def run_query(query):
    request = requests.post("https://api.github.com/graphql", json={"query": query}, headers=headers)
    if request.status_code == 200:
        return request.json()
    else:
        raise Exception("Query failed to run by returning code of {}. {}".format(request.status_code, query))


def get_all_discussion_experts():
    after = ""
    output = []
    while True:
        query = f"""
            query {{
                repository(owner: "tiangolo", name: "fastapi") {{
                    discussions(first: 100{f', after:"{after}"' if after else ''}) {{
                        totalCount # Int!

                        pageInfo {{
                            endCursor
                            hasNextPage
                        }}

                        nodes {{
                            # type: Discussion
                            author {{
                                    login
                                }}
                            answer {{
                                author {{
                                    login
                                }}
                            }}
                        }}
                    }}

                }}
            }}
        """
        result = run_query(query)
        print(result)
        for node in result["data"]["repository"]["discussions"]["nodes"]:
            # Needs an answer and cant be the creator of the discussion
            if (
                (node["answer"] is not None)
                and (node["author"] is not None)
                and (node["author"]["login"] != node["answer"]["author"]["login"])
            ):
                output.append(node["answer"]["author"]["login"])

        if not result["data"]["repository"]["discussions"]["pageInfo"]["hasNextPage"]:
            break
        after = result["data"]["repository"]["discussions"]["pageInfo"]["endCursor"]

    return Counter(output)



result = get_all_discussion_experts()
print(result)
```


